[ExtensionOf(formStr(RetailPeriodicDiscount))]
public final class GUPRetailPeriodicDiscountForm_Extension
{
    private NumberSeqFormHandler numberSeqMarginId;
    private NumberSeqFormHandler numberSeqFreeItemId;
    private InventDimCtrl_Frm gupInventDimFormSetup;

}

Method.Source:
public void init()
{
    next init();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        if (!this.args().parmEnumType())
        {
            GUPFreeItemDiscount.visible(true);
            GUPFreeItemDiscount.enabled(true);
        }

        disableEmptyRGMLCheck = true;
        this.updateDesignGupInventDim(InventDimFormDesignUpdate::Init);
        this.hideRetailControls();
        this.initGupControls();

        RBOMultibuyDiscountLine_priceDiscPct.label("@GlobalUnifiedPricing:GUPRetailDiscountTypeValueLabel");
    }
}

public void run()
{
    next run();

    if (!FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        Concurrency_ConcurrencyMode.delete(enum2Str(RetailDiscountConcurrency::PriceAttributeCombinationPriority));
    }
}

public void hideAllDiscountSpecificControls()
{
    next hideAllDiscountSpecificControls();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        ClaimDistribution_QtyLowest.visible(false);
        DiscountAllocation_QtyLowest.visible(false);
    }
}

public void setControlVisibility()
{
    next setControlVisibility();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && (retailPeriodicDiscount is RetailDiscountOffer))
    {
        DiscountClaimGroup.visible(true);
    }
    else
    {
        DiscountClaimGroup.visible(false);
    }

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && (retailPeriodicDiscount is RetailDiscountMultibuy || retailPeriodicDiscount is RetailDiscountThreshold))
    {
        ClaimDistribution_QtyLowest.visible(true);
        DiscountAllocation_QtyLowest.visible(true);
    }

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        boolean freeItemVisible = retailPeriodicDiscount is GUPFreeItemDiscount;
        boolean leastAmountVisible = retailPeriodicDiscount is RetailDiscountThreshold || retailPeriodicDiscount is GUPFreeItemDiscount;
        boolean isMandatoryVisible = retailPeriodicDiscount is RetailDiscountThreshold || retailPeriodicDiscount is RetailDiscountMixAndMatch || retailPeriodicDiscount is GUPFreeItemDiscount;

        GUPFreeItemDiscountTabPage.visible(freeItemVisible);
        GUPFreeItemLinesTabPage.visible(freeItemVisible);
        RetailPeriodicDiscountLine_GUPFreeItemDiscountLine_FreeItemGroup.visible(freeItemVisible);

        RetailPeriodicDiscountLine_IsMandatory.visible(isMandatoryVisible);
        RetailPeriodicDiscountLine_IsMandatory.enabled(isMandatoryVisible);
        RetailPeriodicDiscountLine_LeastAmount.visible(leastAmountVisible);
        RetailPeriodicDiscountLine_LeastAmount.enabled(leastAmountVisible);

        if (retailPeriodicDiscount is GUPFreeItemDiscount)
        {
            GUPFreeItemDiscount freeItemDiscount = GUPFreeItemDiscount::find(retailPeriodicDiscount.OfferId);
            RetailPeriodicDiscountLine_LeastAmount.enabled(freeItemDiscount.FreeItemCriteriaType == GUPFreeItemCriteriaType::Amount);
            RetailPeriodicDiscountLine_IsMandatory.enabled(freeItemDiscount.FreeItemCriteriaType == GUPFreeItemCriteriaType::Quantity);
            Concurrency_ConcurrencyMode.visible(false);
        }
        else
        {
            Concurrency_ConcurrencyMode.visible(true);
        }

        if (retailPeriodicDiscount.PeriodicDiscountType == RetailDiscountOfferTypeBase::DiscountOffer
            || retailPeriodicDiscount.PeriodicDiscountType == RetailDiscountOfferTypeBase::DiscountOfferLineQuantityLimit)
        {
            DiscountPostingTabPage.visible(true);
            DiscountClaimGroup.visible(true);
        }
        else
        {
            DiscountPostingTabPage.visible(false);
            DiscountClaimGroup.visible(false);
        }

        if (retailPeriodicDiscount is RetailDiscountOffer)
        {
            RetailDiscountOffer discountOffer =  RetailPeriodicDiscount as RetailDiscountOffer;
            FormControl tierConfigurationTab = this.design().controlName(formControlStr(RetailPeriodicDiscount, GUPTierConfigurationTabPage));
            tierConfigurationTab.visible(discountOffer.IsTierConfigurationEnabled);
            tierConfigurationTab.enabled(discountOffer.IsTierConfigurationEnabled);

            FormControl calculateMethod = this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountLine_RetailDiscountLineOffer_CalculateMethod));
            calculateMethod.visible(!discountOffer.IsTierConfigurationEnabled);
            calculateMethod.enabled(!discountOffer.IsTierConfigurationEnabled);

            FormControl discPct = this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountLine_RetailDiscountLineOffer_discPct));
            discPct.visible(!discountOffer.IsTierConfigurationEnabled);
            discPct.enabled(!discountOffer.IsTierConfigurationEnabled);

            FormControl discAmount = this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountLine_RetailDiscountLineOffer_discAmount));
            discAmount.visible(!discountOffer.IsTierConfigurationEnabled);
            discAmount.enabled(!discountOffer.IsTierConfigurationEnabled);
        }
    }
}

public NumberSeqFormHandler numberSeqOfferId()
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        if (!numberSeqMarginId)
        {
            numberSeqMarginId = NumberSeqFormHandler::newForm(GUPParameters::numRefMarginComponentPriceAdjustmentId().NumberSequenceId,
                                                         this,
                                                         RetailPeriodicDiscount_RetailDiscountOffer_ds,
                                                         fieldnum(RetailDiscountOffer, OfferId)
                                                         );
        }

        if (!numberSeqOfferId)
        {
            numberSeqOfferId = NumberSeqFormHandler::newForm(GUPParameters::numRefOfferId().NumberSequenceId,
                                                         this,
                                                         RetailPeriodicDiscount_RetailDiscountOffer_ds,
                                                         fieldnum(RetailDiscountOffer, OfferId)
                                                         );
        }

        if (!numberSeqMixAndMatchId)
        {
            numberSeqMixAndMatchId = NumberSeqFormHandler::newForm(GUPParameters::numRefMixAndMatchId().NumberSequenceId,
                                                            this,
                                                            RetailPeriodicDiscount_RetailDiscountMixAndMatch_ds,
                                                            fieldNum(RetailDiscountMixAndMatch, OfferId)
                                                            );
        }

        if (!numberSeqMultibuyId)
        {
            numberSeqMultibuyId = NumberSeqFormHandler::newForm(GUPParameters::numRefMultibuyDiscountId().NumberSequenceId,
                                                            this,
                                                            RetailPeriodicDiscount_RetailDiscountMultibuy_ds,
                                                            fieldNum(RetailDiscountMultibuy, OfferId)
                                                            );
        }

        if (!numberSeqThresholdId)
        {
            numberSeqThresholdId = NumberSeqFormHandler::newForm(GUPParameters::numRefThresholdDiscountId().NumberSequenceId,
                                                            this,
                                                            RetailPeriodicDiscount_RetailDiscountThreshold_ds,
                                                            fieldNum(RetailDiscountThreshold, OfferId)
                                                            );
        }

        if (!numberSeqFreeItemId)
        {
            numberSeqFreeItemId = NumberSeqFormHandler::newForm(GUPParameters::numRefFreeItemDiscountId().NumberSequenceId,
                                                         this,
                                                         RetailPeriodicDiscount_ds,
                                                         fieldnum(GUPFreeItemDiscount, OfferId)
                                                         );
        }
    }

    NumberSeqFormHandler numberSeqBase = next numberSeqOfferId();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        if (retailPeriodicDiscount is RetailDiscountMixAndMatch)
        {
            return numberSeqMixAndMatchId;
        }
        else if (retailPeriodicDiscount is RetailDiscountMultibuy)
        {
            return numberSeqMultibuyId;
        }
        else if (retailPeriodicDiscount is RetailDiscountThreshold)
        {
            return numberSeqThresholdId;
        }
        else if (periodicDiscountType == RetailDiscountOfferTypeBase::Promotion)
        {
            return numberSeqMarginId;
        }
        else if (retailPeriodicDiscount is GUPFreeItemDiscount)
        {
            return numberSeqFreeItemId;
        }
        else
        {
            return numberSeqOfferId;
        }
    }
    else
    {
        return numberSeqBase;
    }
}

public void close()
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && numberSeqMarginId)
    {
        numberSeqMarginId.formMethodClose();
    }

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && numberSeqFreeItemId)
    {
        numberSeqFreeItemId.formMethodClose();
    }

    next close();
}

public void updateDatePeriodView()
{
    next updateDatePeriodView();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        GUPValidationPeriod.enabled(retailPeriodicDiscount.DateValidationType == RetailDateValidationTypeBase::Advanced);
    }
}

public void refreshFormDatasource(GUPPricingAttributeSourceLevel _sourceLevel)
{
    switch (_sourceLevel)
    {
        case GUPPricingAttributeSourceLevel::Header:
            RetailPeriodicDiscount_ds.research(true);
            break;
        case GUPPricingAttributeSourceLevel::Line:
            RetailPeriodicDiscount_ds.research(true);
            RetailPeriodicDiscountLine_ds.research(true);
            break;
    }
}

public void filterAddPriceAttributeGroupQuery(QueryBuildDataSource qbdsGroup, GUPPricingAttributeSourceLevel _sourceLevel)
{
    QueryBuildDataSource qbdsComb = qbdsGroup.addDataSource(tableNum(GUPPriceComponentCodePriceAttributeGroupCombination));
    qbdsComb.addRange(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, PriceComponentCodeName))
        .value(any2Str(retailPeriodicDiscount.PriceComponentCodeName));

    if (_sourceLevel == GUPPricingAttributeSourceLevel::Header)
    {
        qbdsComb.addLink(fieldNum(GUPPricingAttributeGroup, Name), fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderPriceAttributeGroupName));
        qbdsComb.addGroupByField(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderPriceAttributeGroupName));
        qbdsGroup.addGroupByField(fieldNum(GUPPricingAttributeGroup, Name));
        qbdsGroup.addGroupByField(fieldNum(GUPPricingAttributeGroup, Description));
    }
    else
    {
        qbdsComb.addLink(fieldNum(GUPPricingAttributeGroup, Name), fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, LinePriceAttributeGroupName));

        QueryBuildDataSource qbdsPriceRule = qbdsComb.addDataSource(tableNum(GUPPricingRule));
        qbdsPriceRule.addLink(fieldNum(GUPPricingRule, PriceAttributeGroupName), fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderPriceAttributeGroupName));
        qbdsPriceRule.addRange(fieldNum(GUPPricingRule, RecId)).value(any2Str(retailPeriodicDiscount.HeaderPricingRule));
    }
}

private void updateDesignGupInventDim(InventDimFormDesignUpdate mode)
{
    InventDimParm inventDimParm = InventDimParm::allInventDim();

    switch (mode)
    {
        case InventDimFormDesignUpdate::Init:
            if (!gupInventDimFormSetup)
            {
                gupInventDimFormSetup = InventDimCtrl::newFromForm(this);
            }

            gupInventDimFormSetup.parmSkipOnHandLookUp(true);
            gupInventDimFormSetup.parmDimParmEnabled(inventDimParm);
            gupInventDimFormSetup.parmDimParmVisibleGrid(InventDimParm::siteAndWarehouse());
            gupInventDimFormSetup.formSetControls(true);
            break;
    }

}

public Object inventDimSetupObject()
{
    return gupInventDimFormSetup;
}

[FormControlEventHandler(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscount_PriceComponentCodeName_GeneralTabPage), FormControlEventType::Lookup)]
public static void RetailPeriodicDiscount_PriceComponentCodeName_GeneralTabPage_OnLookup(FormControl sender, FormControlEventArgs e)
{
    SysTableLookup SysTableLookup;
    Query                   query = new Query();
    QueryBuildDataSource    qbds = query.addDataSource(tableNum(GUPPriceComponentCode));
    QueryBuildDataSource    qbdsComponent;

    SysTableLookup = SysTableLookup::newParameters(tableNum(GUPPriceComponentCode), sender);
    SysTableLookup.addLookupfield(fieldNum(GUPPriceComponentCode, Name));
    SysTableLookup.addLookupfield(fieldNum(GUPPriceComponentCode, Description));

    FormDataSource RetailPeriodicDiscount_ds = sender.formRun().dataSource(tableStr(RetailPeriodicDiscount));
    RetailPeriodicDiscount periodicDiscount = RetailPeriodicDiscount_ds.cursor();
    RetailDiscountOfferTypeBase periodicDiscountType = periodicDiscount.PeriodicDiscountType;

    if (periodicDiscountType == RetailDiscountOfferTypeBase::Promotion)
    {
        qbds.addRange(fieldNum(GUPPriceComponentCode, PriceComponent)).value(queryValue(GUPPriceComponent::PriceMarginComponentAdjustment));
    }
    else if (periodicDiscountType == RetailDiscountOfferTypeBase::DiscountOffer ||
             periodicDiscountType == RetailDiscountOfferTypeBase::Multibuy      ||
             periodicDiscountType == RetailDiscountOfferTypeBase::FreeItem      ||
             periodicDiscountType == RetailDiscountOfferTypeBase::MixAndMatch   ||
             periodicDiscountType == RetailDiscountOfferTypeBase::Threshold     ||
             periodicDiscountType == RetailDiscountOfferTypeBase::DiscountOfferLineQuantityLimit)
    {
        qbds.addRange(fieldNum(GUPPriceComponentCode, PriceComponent)).value(queryValue(GUPPriceComponent::RetailDiscounts));
    }

    SysTableLookup.parmQuery(query);
    SysTableLookup.performFormLookup();

    FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
    ce.CancelSuperCall();
}

