[FormControlEventHandler(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscount_GUPFreeItemDiscount_FreeItemCriteriaType), FormControlEventType::Modified)]
public static void RetailPeriodicDiscount_FreeItemCriteriaType_OnModified(FormControl sender, FormControlEventArgs e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        str freeItemCriteriaType = sender.valueStr();

        FormControl freeItemAmount = sender.formRun().design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountLine_LeastAmount));
        freeItemAmount.enabled(freeItemCriteriaType == enum2Str(GUPFreeItemCriteriaType::Amount));

        FormControl freeItemIsMandatory = sender.formRun().design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountLine_IsMandatory));
        freeItemIsMandatory.enabled(freeItemCriteriaType == enum2Str(GUPFreeItemCriteriaType::Quantity));
    }
}

[FormControlEventHandler(formControlStr(RetailPeriodicDiscount, IsTierConfigurationEnabled), FormControlEventType::Modified)]
public static void IsTierConfigurationEnabled_OnModified(FormControl sender, FormControlEventArgs e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        FormCheckBoxControl checkbox = sender as FormCheckBoxControl;

        FormDataSource RetailPeriodicDiscount_ds = sender.formRun().dataSource(tableStr(RetailPeriodicDiscount));
        RetailPeriodicDiscount periodicDiscount = RetailPeriodicDiscount_ds.cursor();
        RetailDiscountOfferTypeBase periodicDiscountType = periodicDiscount.PeriodicDiscountType;

        if (periodicDiscountType == RetailDiscountOfferTypeBase::Promotion && !checkbox.checked())
        {
            GUPTierPriceAdjustmentLine::deleteByOfferId(periodicDiscount.OfferId);
        }

        FormControl tierConfigurationTab = sender.formRun().design().controlName(formControlStr(RetailPeriodicDiscount, GUPTierConfigurationTabPage));
        tierConfigurationTab.visible(checkbox.checked());
        tierConfigurationTab.enabled(checkbox.checked());

        FormControl calculateMethod = sender.formRun().design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountLine_RetailDiscountLineOffer_CalculateMethod));
        calculateMethod.visible(!checkbox.checked());
        calculateMethod.enabled(!checkbox.checked());

        FormControl discPct = sender.formRun().design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountLine_RetailDiscountLineOffer_discPct));
        discPct.visible(!checkbox.checked());
        discPct.enabled(!checkbox.checked());

        FormControl discAmount = sender.formRun().design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountLine_RetailDiscountLineOffer_discAmount));
        discAmount.visible(!checkbox.checked());
        discAmount.enabled(!checkbox.checked());
    }
}

[FormControlEventHandler(formControlStr(RetailPeriodicDiscount, Tier_AdjustmentType), FormControlEventType::Modified)]
public static void Tier_AdjustmentType_OnModified(FormControl sender, FormControlEventArgs e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        FormComboBoxControl adjustmentTypeControl = sender as FormComboBoxControl;
        str adjustmentType = adjustmentTypeControl.valueStr();
        FormDataSource retailPeriodicDiscountLine_RetailDiscountLineOffer_ds = sender.formRun().dataSource(tableStr(RetailPeriodicDiscountLine));
        switch (adjustmentType)
        {
            case enum2Str(GUPPriceTermCalculateMethod::FixedAmount):
                retailPeriodicDiscountLine_RetailDiscountLineOffer_ds.object(fieldnum(RetailDiscountLineOffer, UnitAppliesToAll)).enabled(true);
                break;
            case enum2Str(GUPPriceTermCalculateMethod::Percent):
                retailPeriodicDiscountLine_RetailDiscountLineOffer_ds.object(fieldnum(RetailDiscountLineOffer, UnitAppliesToAll)).enabled(false);
                break;
        }
    }
}

private void hideRetailControlsForMarginComponentCode()
{
    if (periodicDiscountType == RetailDiscountOfferTypeBase::Promotion)
    {
        this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscount_OfferId1)).visible(false);
        this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscount_PeriodicDiscountType)).visible(false);
        this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscount_PeriodicDiscountType1)).visible(false);
        this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscount_DiscountPercentValue)).visible(false);
        this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountLine_RetailDiscountLineOffer_offerPrice)).visible(false);
        this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountLine_RetailDiscountLineOffer_discountMethod)).visible(false);

        PeriodicDiscount_OfferLedgerDimension.visible(false);
        Concurrency.visible(false);
        ValidationPeriod.visible(false);
        DiscountOfferTabPage.visible(false);
        PriceAdjustments.visible(false);
    }
}

private void hideRetailControls()
{
    this.hideRetailControlsForMarginComponentCode();
    this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscount_Name)).visible(false);
    this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountCopyList)).visible(false);
    this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailDiscountPriceGroupMenuItemButton)).visible(false);
    this.design().controlName(formControlStr(RetailPeriodicDiscount, ViewSharedProductsButton)).visible(false);
    this.design().controlName(formControlStr(RetailPeriodicDiscount, AllDiscountsLineButtonGroup)).visible(false);
    this.design().controlName(formControlStr(RetailPeriodicDiscount, AllDiscountsLineButtonGroupThresholdApplying)).visible(false);
    this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailGroupMemberLineGroup)).visible(false);
    this.design().controlName(formControlStr(RetailPeriodicDiscount, ThresholdApplyingLines_RetailGroupMemberLineGroup)).visible(false);
    this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountLine_RetailDiscountLineOffer_discountMethodN1)).visible(false);
    this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountLine_RetailDiscountLineOffer_offerPriceN1)).visible(false);
    this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountLine_RetailDiscountLineOffer_offerPriceInclTaxN1)).visible(false);

    AddProducts.visible(false);
    AddProductsThresholdApplying.visible(false);
    InventoryDimension.visible(false);
    ThresholdApplyingLines_InventoryDimension.visible(false);
    Account.visible(false);
    MatchAllAssociatedPriceGroups.visible(false);
    PriorityGroup.visible(false);
    ModeOfDelivery.visible(false);
}

private void initGupControls()
{
    this.initGupDiscountOfferControls();
    this.initGupDiscountThresholdControls();
    this.initGupDiscountMixAndMatchControls();
    this.initGupDiscountMultibuyControls();
    this.initGupMarginComponentControls();
    this.initGupFreeItemDiscountControls();

    GUPCaclulationTabPage.visible(true);
    GUPPeriodicDiscountCopy.visible(true);
    EditHeaderPricingAttrGrp.visible(true);
    GUPDiscountPriceComponentGroupExclusionList.visible(periodicDiscountType != RetailDiscountOfferTypeBase::Promotion);
    PriceComponentCodeGroup.visible(true);

    RetailPeriodicDiscount_PriceComponentCodeName_GeneralTabPage.visible(true);
