public void setDatasourceEditability()
{
    next setDatasourceEditability();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        boolean isDiscountDisabled = !retailPeriodicDiscount.Status;

        EditHeaderPricingAttrGrp.enabled(isDiscountDisabled);
        GUPDiscountPriceComponentGroupExclusionList.enabled(isDiscountDisabled);
        EditLinePricingAttrGrp.enabled(isDiscountDisabled);
        EditLinePricingAttrGrpThresholdApplying.enabled(isDiscountDisabled);
        GUPPeriodicDiscountLineCopy.enabled(isDiscountDisabled);

        GUPPeriodicDiscountAllocation_ds.allowEdit(isDiscountDisabled);
        GUPPeriodicDiscountAllocation_ds.allowCreate(isDiscountDisabled);
        GUPPeriodicDiscountAllocation_ds.allowDelete(isDiscountDisabled);

        GUPPeriodicDiscountClaimDistribution_ds.allowEdit(isDiscountDisabled);
        GUPPeriodicDiscountClaimDistribution_ds.allowCreate(isDiscountDisabled);
        GUPPeriodicDiscountClaimDistribution_ds.allowDelete(isDiscountDisabled);

        GUPFreeItemDiscountTabPage.enabled(isDiscountDisabled);

        GUPFreeItemDiscountTiers_ds.allowEdit(isDiscountDisabled);
        GUPFreeItemDiscountTiers_ds.allowCreate(isDiscountDisabled);
        GUPFreeItemDiscountTiers_ds.allowDelete(isDiscountDisabled);

        GUPFreeItemLine_ds.allowEdit(isDiscountDisabled);
        GUPFreeItemLine_ds.allowCreate(isDiscountDisabled);
        GUPFreeItemLine_ds.allowDelete(isDiscountDisabled);

        Tier_AdjustmentType.enabled(isDiscountDisabled);
        IsTierConfigurationEnabled.enabled(isDiscountDisabled);
        GUPTierPriceAdjustmentLine_ds.allowEdit(isDiscountDisabled);
        GUPTierPriceAdjustmentLine_ds.allowCreate(isDiscountDisabled);
        GUPTierPriceAdjustmentLine_ds.allowDelete(isDiscountDisabled);

        this.design().controlName(formControlStr(RetailPeriodicDiscount, Discount_discountType)).enabled(isDiscountDisabled);
    }
}

public void customizeMenuOptions(OfficeMenuOptions _menuOptions)
{
    next customizeMenuOptions(_menuOptions);
    str name = this.args().menuItemName();

    if (!FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        ListIterator dataEntityIterator = new ListIterator(_menuOptions.dataEntityOptions());
        while (dataEntityIterator.more())
        {
            if (dataEntityIterator.value().dataEntityName() == dataentityviewstr(GUPMarginComponentPriceAdjustmentEntity) 
                || dataEntityIterator.value().dataEntityName() == dataentityviewstr(GUPRetailDiscountEntity))
            {
                dataEntityIterator.delete();
            }
            else
            {
                dataEntityIterator.next();
            }
        }
    }
    else
    {
        if (this.args().menuItemName() == menuItemDisplayStr(RetailDiscountPromotion)
        || this.args().menuItemName() == menuItemDisplayStr(GUPMarginComponentPriceAdjustments))
        {
            // Clear the menu option related to standard discount entity, which are driven by the root data source of an entity.
            ListIterator dataEntityIterator = new ListIterator(_menuOptions.dataEntityOptions());
            while (dataEntityIterator.more())
            {
                if (dataEntityIterator.value().dataEntityName() == dataentityviewstr(RetailDiscountEntity) 
                    || dataEntityIterator.value().dataEntityName() == dataentityviewstr(GUPRetailDiscountEntity))
                {
                    dataEntityIterator.delete();
                }
                else
                {
                    dataEntityIterator.next();
                }
            }

            _menuOptions.dataEntityOptions()
            .addEnd(OfficeMenuDataEntityOptions::construct(tableStr(GUPMarginComponentPriceAdjustmentLineEntity)));
            _menuOptions.dataEntityOptions()
            .addEnd(OfficeMenuDataEntityOptions::construct(tableStr(GUPMarginComponentPriceAdjustmentTierLineEntity)));
        }
        else
        {
            // Clear the menu option related to margin component price adjustment entity, which are driven by the root data source of an entity.
            ListIterator dataEntityIterator = new ListIterator(_menuOptions.dataEntityOptions());
            while (dataEntityIterator.more())
            {
                if (dataEntityIterator.value().dataEntityName() == dataentityviewstr(GUPMarginComponentPriceAdjustmentEntity) 
                    || dataEntityIterator.value().dataEntityName() == dataentityviewstr(RetailDiscountEntity))
                {
                    dataEntityIterator.delete();
                }
                else
                {
                    dataEntityIterator.next();
                }
            }

            _menuOptions.dataEntityOptions()
            .addEnd(OfficeMenuDataEntityOptions::construct(tableStr(GUPRetailDiscountLineEntity)));
        }
    }
}

void updateDiscountOfferLineView()
{
    next updateDiscountOfferLineView();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && retailPeriodicDiscountLine is RetailDiscountLineOffer)
    {
        RetailDiscountOffer discountOffer =  RetailPeriodicDiscount::findByOfferId(retailPeriodicDiscountLine_RetailDiscountLineOffer.OfferId) as RetailDiscountOffer;
        if (discountOffer.IsTierConfigurationEnabled == NoYes::Yes)
        {
            if (discountOffer.TierPriceAdjustmentMethod == GUPPriceTermCalculateMethod::FixedAmount)
            {
                retailPeriodicDiscountLine_RetailDiscountLineOffer_ds.object(fieldnum(RetailDiscountLineOffer, UnitAppliesToAll)).enabled(true);
            }
            else
            {
                retailPeriodicDiscountLine_RetailDiscountLineOffer.UnitAppliesToAll = NoYes::No;
                retailPeriodicDiscountLine_RetailDiscountLineOffer_ds.object(fieldnum(RetailDiscountLineOffer, UnitAppliesToAll)).enabled(false);
            }
        }
        else
        {
            if (retailPeriodicDiscountLine_retailDiscountLineOffer.discountMethod == RetailDiscountOfferLineDiscMethodBase::PercentOff)
            {
                retailPeriodicDiscountLine_RetailDiscountLineOffer.UnitAppliesToAll = NoYes::No;
                retailPeriodicDiscountLine_RetailDiscountLineOffer_ds.object(fieldnum(RetailDiscountLineOffer, UnitAppliesToAll)).enabled(false);
            }
            else
            {
                retailPeriodicDiscountLine_RetailDiscountLineOffer_ds.object(fieldnum(RetailDiscountLineOffer, UnitAppliesToAll)).enabled(true);
            }
        }
    }
}
